CREATE TABLE IF NOT EXISTS message_analysis_metadata (id INTEGER PRIMARY KEY, message_analysis_id INTEGER UNIQUE, email_analysis_id INTEGER UNIQUE, user_id VARCHAR(160) NOT NULL, input_type VARCHAR(30) NOT NULL, sender VARCHAR(512), subject TEXT, risk_score INTEGER, classification VARCHAR(120), ml_prediction INTEGER, ml_confidence FLOAT, llm_status VARCHAR(40), model_version VARCHAR(160), analysis_status VARCHAR(30) NOT NULL DEFAULT 'COMPLETED', duplicate_of_id INTEGER, created_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id), FOREIGN KEY(email_analysis_id) REFERENCES email_analyses(id));
CREATE INDEX IF NOT EXISTS ix_message_analysis_metadata_user_id ON message_analysis_metadata(user_id);
CREATE INDEX IF NOT EXISTS ix_message_analysis_metadata_created_at ON message_analysis_metadata(created_at);
CREATE TABLE IF NOT EXISTS message_contents (id INTEGER PRIMARY KEY, message_analysis_id INTEGER UNIQUE NOT NULL, content_bytes BLOB NOT NULL, sha256 VARCHAR(64) NOT NULL, content_type VARCHAR(80) NOT NULL, protected VARCHAR(10) NOT NULL DEFAULT 'true', created_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id));
CREATE INDEX IF NOT EXISTS ix_message_contents_sha256 ON message_contents(sha256);
CREATE TABLE IF NOT EXISTS message_analysis_events (id INTEGER PRIMARY KEY, message_analysis_id INTEGER, email_analysis_id INTEGER, user_id VARCHAR(160) NOT NULL, event_type VARCHAR(60) NOT NULL, details_json TEXT NOT NULL, created_at TIMESTAMP, FOREIGN KEY(message_analysis_id) REFERENCES message_analysis_records(id), FOREIGN KEY(email_analysis_id) REFERENCES email_analyses(id));
CREATE INDEX IF NOT EXISTS ix_message_analysis_events_message_analysis_id ON message_analysis_events(message_analysis_id);
CREATE INDEX IF NOT EXISTS ix_message_analysis_events_email_analysis_id ON message_analysis_events(email_analysis_id);
